pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a recipient contract that reverts on receive (no receive/fallback)
        RevertingRecipient recipient = new RevertingRecipient();
        // Fund the C contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Owner (address(this)) calls withdrawAll with the reverting recipient
        bool ok;
        try c.withdrawAll(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (transfer) reverts => ok == false.
        // Bug (send) does not revert => ok == true.
        // So assertFalse asserts the reference behavior; bug will make it fail.
        assertFalse(ok);
    }
}

contract RevertingRecipient {
